// Theme commands. The base theme is a shadcn preset; accent themes for runtime switching
// are generated by running `shadcn init --preset` once per official theme.
import type { Command } from "commander"
import { cpSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import path from "node:path"
import { PRESET_BASE_COLORS, PRESET_THEMES, decodePreset, encodePreset } from "shadcn/preset"
import { capture, root, run } from "../run.ts"

const CSS_OUT = path.join(root, "src/styles/themes.css")
const JSON_OUT = path.join(root, "src/styles/themes.json")

export function register(program: Command): void {
  const theme = program.command("theme").description("The shadcn preset and accent themes")

  theme.command("show").description("Show the project's current shadcn preset")
    .action(() => run("shadcn", ["preset", "resolve"]))

  theme.command("set").description("Switch the base preset (build codes at ui.shadcn.com/create), then regenerate the accent themes from it")
    .argument("<code>", "shadcn preset code")
    .action((code: string) => {
      run("shadcn", ["init", "--preset", code, "--force", "--reinstall", "--yes"])
      generate()
    })

  theme.command("gen").description("Regenerate src/styles/themes.css and themes.json from shadcn presets (~20s per theme)")
    .option("--json-only", "only rebuild themes.json from the existing themes.css")
    .action((opts: { jsonOnly?: boolean }) => (opts.jsonOnly ? writeJson(readFileSync(CSS_OUT, "utf8")) : generate()))
}

function currentPreset() {
  const code = capture("shadcn", ["preset", "resolve"]).match(/code\s+(\S+)/)?.[1]
  if (!code) throw new Error("Could not read the current preset from `shadcn preset resolve`")
  return { code, config: decodePreset(code) }
}

/** The body of the first `selector { … }` block in a CSS file. */
function block(css: string, selector: string): string {
  const start = css.indexOf("{", css.indexOf(selector + " {")) + 1
  return css.slice(start, css.indexOf("}", start)).trim()
}

function generate(): void {
  const { code, config } = currentPreset()
  if (!config) throw new Error(`Could not decode preset ${code}`)
  // The base colour itself (plain look) plus every theme that isn't a base colour
  const baseColors: readonly string[] = PRESET_BASE_COLORS
  const themes = [config.baseColor, ...PRESET_THEMES.filter((t) => !baseColors.includes(t))]

  let css = `/* Generated by \`npm run theme:gen\` from shadcn presets. Do not edit by hand.
   Base preset: ${code} (baseColor ${config.baseColor}). Switch at runtime with <html data-accent="…">. */\n`

  for (const name of themes) {
    const preset = encodePreset({ ...config, theme: name, chartColor: name })
    // Scratch copy of the project so shadcn init can rewrite index.css without touching ours
    const dir = mkdtempSync(path.join(tmpdir(), "theme-"))
    for (const f of ["package.json", "components.json", "tsconfig.json", "tsconfig.app.json", "vite.config.ts", "src"])
      cpSync(path.join(root, f), path.join(dir, f), { recursive: true })
    symlinkSync(path.join(root, "node_modules"), path.join(dir, "node_modules"))
    capture("shadcn", ["init", "--preset", preset, "--force", "--no-reinstall", "--yes"], { cwd: dir })
    const out = readFileSync(path.join(dir, "src/styles/index.css"), "utf8")
    rmSync(dir, { recursive: true, force: true })

    css += `\n/* ${name} — preset ${preset} */\n:root[data-accent="${name}"] {\n  ${block(out, ":root")}\n}\n`
    css += `:root.dark[data-accent="${name}"] {\n  ${block(out, ".dark")}\n}\n`
    console.log(`${name.padEnd(8)} ${preset}`)
  }

  writeFileSync(CSS_OUT, css)
  console.log(`wrote src/styles/themes.css (${themes.length} themes)`)
  writeJson(css, config.theme)
}

/** themes.json: the list the switcher shows, with each theme's light --primary for the swatch. */
function writeJson(css: string, defaultTheme: string = currentPreset().config?.theme ?? "neutral"): void {
  const re = /\/\* (\S+) — preset (\S+) \*\/\n:root\[data-accent="[^"]+"\] \{([^}]*)\}/g
  const themes = [...css.matchAll(re)].map(([, name, preset, body]) => ({
    name,
    preset,
    primary: body.match(/--primary:\s*([^;]+);/)?.[1].trim() ?? "",
  }))
  writeFileSync(JSON_OUT, JSON.stringify({ default: defaultTheme, themes }, null, 2) + "\n")
  console.log(`wrote src/styles/themes.json (${themes.length} themes)`)
}
